// ==UserScript==
// @name         Citi Offer Lite
// @namespace    https://github.com/yangzichao/card-offer-hub
// @version      1.0.1
// @description  Manually select Citi cards, scan Merchant Offers, and enroll all available offers serially
// @author       Zichao Yang
// @match        https://online.citi.com/US/*
// @grant        GM_getValue
// @grant        GM_setValue
// @noframes
// @run-at       document-idle
// @homepageURL  https://github.com/yangzichao/card-offer-hub/tree/main/issuers/citi/citi-offer-lite
// @supportURL   https://github.com/yangzichao/card-offer-hub/issues
// @updateURL    https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/citi-offer-lite.user.js
// @downloadURL  https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/citi-offer-lite.user.js
// ==/UserScript==
// Generated from issuers/citi/citi-offer-lite/src by "npm run build". Do not edit this file.
// Installing from https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/citi-offer-lite.user.js lets Tampermonkey update it on its own.

(function () {
    'use strict';

    // Source: core/state.js
    const SETTINGS = {
        id: "citi-offer-lite", name: "Citi Offer Lite", version: "1.0.1",
        apiBase: '/gcgapi/prod/public/v1',
        retrievePath: '/digital/customers/creditCards/merchantOffers/retrieve',
        enrollmentPath: '/digital/customers/creditCards/accounts/rewards/specialOffers/enrollMerchantOffer',
        gapMilliseconds: 500, timeoutMilliseconds: 45000,
        defaultCooldownMilliseconds: 300000
    };
    const state = {
        accounts: [], selected: new Set(), offers: [], busy: false, stopRequested: false,
        needsScan: false, nextRequestAt: 0, cooldownUntil: 0, storageError: '',
        status: 'Open Merchant Offers, then detect cards. Nothing runs automatically.',
        confirmed: 0, completed: 0, total: 0, panel: null, collapsed: false, search: ''
    };
    function updateStatus(message) {
        state.status = message;
        renderPanel();
    }
    function ensureRunning() {
        if (state.stopRequested) throw new Error('Stopped. Scan again before adding more offers.');
        if (location.origin !== 'https://online.citi.com' || !/^\/US\/(?:ag|nga)\//.test(location.pathname)) {
            throw new Error('Open a signed-in Citi page and scan again.');
        }
    }
    function stopRun() {
        state.stopRequested = true;
        updateStatus('Stopping after the current request settles. Its result may still be confirmed.');
    }

    // Source: core/storage.js
    // Store only pacing state. Account IDs, offers, cookies, and request headers stay
    // in memory; a reload always requires fresh discovery and manual card selection.
    function restorePacing() {
        try {
            const saved = GM_getValue(`${SETTINGS.id}:pacing`, null);
            if (saved === null) return;
            if (saved.schemaVersion !== 1 || !Number.isFinite(saved.cooldownUntil)
                || !Number.isFinite(saved.nextRequestAt)) {
                throw new Error('Unsupported pacing snapshot; stored data was preserved.');
            }
            state.cooldownUntil = Math.max(state.cooldownUntil, saved.cooldownUntil);
            state.nextRequestAt = Math.max(state.nextRequestAt, saved.nextRequestAt);
        } catch {
            state.storageError = 'Cannot read pacing storage. Resolve Tampermonkey storage before running.';
        }
    }
    function savePacing() {
        try {
            GM_setValue(`${SETTINGS.id}:pacing`, {
                schemaVersion: 1, cooldownUntil: state.cooldownUntil, nextRequestAt: state.nextRequestAt
            });
        } catch {
            state.storageError = 'Cannot save pacing storage. Further requests are blocked; reload after fixing storage.';
            renderPanel();
        }
    }

    // Source: api/session.js
    function readCookie(cookieName) {
        const prefix = `${cookieName}=`;
        const entry = document.cookie.split(';').map(value => value.trim()).find(value => value.startsWith(prefix));
        if (!entry) return '';
        try { return decodeURIComponent(entry.slice(prefix.length)); } catch { return ''; }
    }
    function sessionHeaders() {
        // Citi's establishCookiePackage writes these routing values on sign-in.
        // Read current values for each request, never copy a HAR's session values.
        const headers = { Accept: 'application/json', 'Content-Type': 'application/json', environmentID: 'SuperMarioPROD' };
        for (const name of ['appVersion', 'businessCode', 'channelId', 'client_id', 'countryCode']) {
            const value = readCookie(name);
            if (!value || value === 'undefined' || value === 'null') {
                throw new Error('Citi session configuration is unavailable. Open Merchant Offers after signing in, then scan again.');
            }
            headers[name] = value;
        }
        const sessionId = readCookie('tmx_sessionid');
        if (!sessionId) throw new Error('Citi session is not ready. Open Merchant Offers and scan again.');
        headers.TMXSessionId = sessionId;
        const xsrfToken = readCookie('XSRF-TOKEN');
        if (xsrfToken) headers['X-XSRF-TOKEN'] = xsrfToken;
        return headers;
    }

    // Source: api/transport.js
    function retryAfterMilliseconds(value, now = Date.now()) {
        if (typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value.trim())) return Number(value) * 1000;
        const deadline = typeof value === 'string' ? Date.parse(value) : NaN;
        return Number.isFinite(deadline) ? Math.max(0, deadline - now) : SETTINGS.defaultCooldownMilliseconds;
    }
    async function waitForRequestSlot() {
        while (Date.now() < state.nextRequestAt) {
            ensureRunning();
            await new Promise(resolve => setTimeout(resolve, Math.min(250, state.nextRequestAt - Date.now())));
        }
        ensureRunning();
        if (state.storageError) throw new Error(state.storageError);
        if (Date.now() < state.cooldownUntil) {
            throw new Error(`Rate limited. Try a new scan after ${new Date(state.cooldownUntil).toLocaleTimeString()}.`);
        }
    }
    async function requestJson(path, body) {
        if (![SETTINGS.retrievePath, SETTINGS.enrollmentPath].includes(path)) throw new Error('Unsupported Citi endpoint.');
        await waitForRequestSlot();
        const headers = sessionHeaders();
        // Reserve a slot before sending. A reload or closed tab releases Web Locks,
        // but must not permit a new tab to immediately overlap this pending request.
        state.nextRequestAt = Date.now() + SETTINGS.timeoutMilliseconds + SETTINGS.gapMilliseconds;
        savePacing();
        if (state.storageError) throw new Error(state.storageError);
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), SETTINGS.timeoutMilliseconds);
        try {
            const response = await fetch(SETTINGS.apiBase + path, {
                method: 'POST', credentials: 'same-origin', redirect: 'error',
                headers, body: JSON.stringify(body), signal: controller.signal
            });
            if (response.status === 429) {
                state.cooldownUntil = Math.max(state.cooldownUntil,
                    Date.now() + retryAfterMilliseconds(response.headers.get('Retry-After')));
            }
            // Include body consumption in the response-completion pacing boundary.
            const responseText = await response.text();
            if (response.status === 429) throw new Error('Citi returned HTTP 429. Cooling down; scan again later.');
            if (!response.ok) throw new Error(`Citi returned HTTP ${response.status}. Scan again after resolving the error.`);
            let payload;
            try { payload = JSON.parse(responseText); }
            catch { throw new Error('Citi returned a non-JSON response. Sign in and scan again.'); }
            return payload;
        } catch (error) {
            // Do not display browser errors that could contain URLs or session data.
            if (error.name === 'AbortError') throw new Error('Request timed out; result is unconfirmed. Scan again.');
            if (error instanceof TypeError) throw new Error('Network request failed; result is unconfirmed. Scan again.');
            throw error;
        } finally {
            clearTimeout(timeout);
            state.nextRequestAt = Date.now() + SETTINGS.gapMilliseconds;
            savePacing();
        }
    }

    // Source: api/contracts.js
    function normalizeAccounts(payload) {
        if (!Array.isArray(payload?.cardArtDetails)) throw new Error('Citi card-list response was not recognized.');
        const accounts = new Map();
        for (const card of payload.cardArtDetails) {
            if (typeof card.accountId !== 'string' || !card.accountId.trim()
                || typeof card.displayProductName !== 'string') throw new Error('Citi returned an incomplete card record.');
            accounts.set(card.accountId, { accountId: card.accountId, name: card.displayProductName });
        }
        return [...accounts.values()];
    }
    function normalizeOffers(payload, accountId) {
        if (!Array.isArray(payload?.merchantOffers)) throw new Error('Citi offer-list response was not recognized.');
        const offers = new Map();
        for (const group of payload.merchantOffers) {
            if (!Array.isArray(group.offers)) throw new Error('Citi returned an incomplete offer category.');
            for (const raw of group.offers) {
                if (typeof raw.offerId !== 'string' || !raw.offerId.trim() || typeof raw.offerStatus !== 'string') {
                    throw new Error('Citi returned an incomplete offer record.');
                }
                const existing = offers.get(raw.offerId);
                const status = raw.offerStatus.toUpperCase();
                if (existing) {
                    // Conflicting duplicates must never turn an enrolled/unknown
                    // offer back into an AVAILABLE enrollment candidate.
                    if (existing.status !== status) existing.status = 'CONFLICT';
                    continue;
                }
                offers.set(raw.offerId, {
                    accountId, offerId: raw.offerId, status,
                    merchant: typeof raw.merchantName === 'string' ? raw.merchantName : 'Merchant',
                    title: typeof raw.offerTitle === 'string' ? raw.offerTitle : '',
                    category: group.displayOffersCategory || '', expires: raw.offerEndDate || ''
                });
            }
        }
        return [...offers.values()];
    }
    function enrollmentBody(offer) {
        return { offerId: offer.offerId, accountId: offer.accountId, oneClickEnroll: 'true' };
    }
    function enrollmentConfirmed(payload, offer) {
        const enrollmentId = payload?.EnrolledOfferInfo?.enrollmentId;
        const details = payload?.MerchantOfferDetails;
        if (typeof enrollmentId !== 'string' || !enrollmentId.trim() || !details || typeof details !== 'object'
            || Array.isArray(details) || !Object.keys(details).length) return false;
        if (details.offerId !== undefined && details.offerId !== offer.offerId) return false;
        if (details.accountId !== undefined && details.accountId !== offer.accountId) return false;
        if (details.offerStatus !== undefined && String(details.offerStatus).toUpperCase() !== 'ENROLLED') return false;
        if (payload.EnrolledOfferInfo.accountId !== undefined && payload.EnrolledOfferInfo.accountId !== offer.accountId) return false;
        if (payload.EnrolledOfferInfo.offerId !== undefined && payload.EnrolledOfferInfo.offerId !== offer.offerId) return false;
        return true;
    }

    // Source: workflows/runner.js
    async function runExclusive(action) {
        if (state.busy) return;
        state.busy = true;
        state.stopRequested = false;
        renderPanel();
        const execute = async () => {
            restorePacing();
            if (state.storageError) throw new Error(state.storageError);
            ensureRunning();
            await action();
        };
        try {
            // Prevent two tabs running this script from enrolling simultaneously.
            if (!navigator.locks?.request) throw new Error('This browser does not support the required tab lock. Use current Chrome.');
            await navigator.locks.request(SETTINGS.id, { ifAvailable: true }, async lock => {
                if (!lock) throw new Error('Citi Offer Lite is running in another tab. Wait for it to finish.');
                await execute();
            });
        } catch (error) {
            state.needsScan = true;
            updateStatus(error.message);
        } finally {
            state.busy = false;
            renderPanel();
        }
    }
    function setCardSelected(accountId, selected) {
        if (state.busy || !state.accounts.some(card => card.accountId === accountId)) return;
        if (selected) state.selected.add(accountId); else state.selected.delete(accountId);
        state.offers = [];
        renderPanel();
    }

    // Source: workflows/offers.js
    function detectCards() {
        return runExclusive(async () => {
            state.accounts = [];
            state.selected.clear();
            state.offers = [];
            updateStatus('Detecting eligible cards…');
            const payload = await requestJson(SETTINGS.retrievePath, {});
            ensureRunning();
            state.accounts = normalizeAccounts(payload);
            // The default response's offers belong to Citi's default card, never
            // assume they belong to a selected card. Scan every selected ID explicitly.
            updateStatus(`Detected ${state.accounts.length} cards. Select the cards you want to enroll.`);
        });
    }
    async function scanSelectedCards(accounts) {
        state.offers = [];
        state.confirmed = 0;
        state.completed = 0;
        state.total = 0;
        for (const [index, card] of accounts.entries()) {
            ensureRunning();
            updateStatus(`Scanning card ${index + 1}/${accounts.length}; requests are spaced 0.5 seconds apart…`);
            const payload = await requestJson(SETTINGS.retrievePath, { accountId: card.accountId });
            ensureRunning();
            state.offers.push(...normalizeOffers(payload, card.accountId));
            renderPanel();
        }
        state.needsScan = false;
    }
    function scanOffers() {
        const accounts = state.accounts.filter(card => state.selected.has(card.accountId));
        if (!accounts.length) return;
        return runExclusive(async () => {
            await scanSelectedCards(accounts);
            updateStatus(`Scan complete: ${state.offers.filter(offer => offer.status === 'AVAILABLE').length} available across ${accounts.length} selected cards.`);
        });
    }
    function addAllOffers() {
        const accounts = state.accounts.filter(card => state.selected.has(card.accountId));
        if (!accounts.length || state.needsScan) return;
        return runExclusive(async () => {
            await scanSelectedCards(accounts);
            const queue = state.offers.filter(offer => offer.status === 'AVAILABLE');
            state.total = queue.length;
            for (const offer of queue) {
                ensureRunning();
                updateStatus(`Adding ${state.completed + 1}/${state.total}: ${offer.merchant}. Waiting for the next request slot…`);
                try {
                    const payload = await requestJson(SETTINGS.enrollmentPath, enrollmentBody(offer));
                    if (!enrollmentConfirmed(payload, offer)) throw new Error('Enrollment was not explicitly confirmed. Scan again before continuing.');
                    offer.status = 'ENROLLED';
                    state.confirmed++;
                    state.completed++;
                    renderPanel();
                } catch (error) {
                    offer.status = 'UNCONFIRMED';
                    throw error;
                }
            }
            ensureRunning();
            updateStatus(`Finished: ${state.confirmed}/${state.total} confirmed. Refresh Citi's page to update its offer badges.`);
        });
    }

    // Source: ui/styles.js
    const PANEL_STYLES = `
    :host{all:initial;position:fixed;bottom:18px;right:18px;z-index:2147483646;font:13px/1.5 system-ui,sans-serif;color:#253247}
    *{box-sizing:border-box} .panel{width:min(440px,calc(100vw - 24px));max-height:85vh;overflow:auto;background:white;border:1px solid #d7dfe8;border-radius:12px;box-shadow:0 10px 36px #19304926}
    header,section,footer{padding:12px 16px} header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e5eaf0} h2{font-size:16px;margin:0}p{margin:6px 0}
    button,input{font:inherit}button{padding:7px 10px;border:1px solid #c7d2df;border-radius:6px;background:#f7f9fc;color:#253247;cursor:pointer}button.primary{background:#1763a6;color:white;border-color:#1763a6}button:disabled{opacity:.45;cursor:not-allowed}
    .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.muted{color:#637185;font-size:12px}.cards{max-height:160px;overflow:auto}.card{display:flex;gap:8px;padding:6px 0}.card input{flex:none}
    input[type=search]{width:100%;padding:8px;border:1px solid #c7d2df;border-radius:6px}.offers{max-height:190px;overflow:auto}.offer{padding:8px 0;border-bottom:1px solid #e5eaf0;overflow-wrap:anywhere}.offer small{display:block;color:#637185}
    footer{background:#f6f8fb;overflow-wrap:anywhere}.error{color:#a13030}[hidden]{display:none!important}
    `;

    // Source: ui/panel.js
    function mountPanel() {
        if (document.getElementById(SETTINGS.id)) return;
        const host = document.createElement('div');
        host.id = SETTINGS.id;
        const panel = host.attachShadow({ mode: 'open' });
        panel.innerHTML = `<style>${PANEL_STYLES}</style><div class="panel">
          <header><h2></h2><button id="collapse" aria-label="Minimize Citi panel">−</button></header>
          <div id="body"><section>
            <p class="muted">Select cards, then add all available Merchant Offers. About 4 offers/minute. No automatic retries.</p>
            <button id="detect" aria-label="Detect Citi cards">Detect cards</button>
            <div id="cards" class="cards"></div>
            <div class="actions"><button id="scan" aria-label="Scan selected Citi cards">Scan selected</button>
            <button id="add" class="primary" aria-label="Scan and add all Citi offers">Scan & add all</button>
            <button id="stop" aria-label="Stop Citi enrollment">Stop</button></div>
            <p class="muted">All selected cards are processed. Search below only filters the display.</p>
          </section><section><p id="counts"></p><input id="search" type="search" aria-label="Search Citi offers" placeholder="Search merchants">
          <div id="offers" class="offers"></div></section>
          <footer><div id="status" role="status" aria-live="polite"></div><div id="storage-error" class="error" role="alert"></div></footer></div></div>`;
        panel.querySelector('h2').textContent = `${SETTINGS.name} ${SETTINGS.version}`;
        panel.getElementById('detect').addEventListener('click', detectCards);
        panel.getElementById('scan').addEventListener('click', scanOffers);
        panel.getElementById('add').addEventListener('click', addAllOffers);
        panel.getElementById('stop').addEventListener('click', stopRun);
        panel.getElementById('search').addEventListener('input', event => { state.search = event.target.value; renderOffers(); });
        panel.getElementById('collapse').addEventListener('click', () => {
            state.collapsed = !state.collapsed;
            panel.getElementById('body').hidden = state.collapsed;
            panel.getElementById('collapse').textContent = state.collapsed ? '+' : '−';
            panel.getElementById('collapse').setAttribute('aria-label', state.collapsed ? 'Expand Citi panel' : 'Minimize Citi panel');
        });
        document.body.appendChild(host);
        state.panel = panel;
        renderPanel();
    }

    // Source: ui/render.js
    function renderOffers() {
        if (!state.panel) return;
        const container = state.panel.getElementById('offers');
        container.replaceChildren();
        const search = state.search.trim().toLowerCase();
        const visible = state.offers.filter(offer => `${offer.merchant} ${offer.title}`.toLowerCase().includes(search));
        for (const offer of visible.slice(0, 200)) {
            const row = document.createElement('div');
            row.className = 'offer';
            const title = document.createElement('strong');
            title.textContent = `${offer.merchant} · ${offer.title}`;
            const detail = document.createElement('small');
            const card = state.accounts.find(account => account.accountId === offer.accountId);
            detail.textContent = `${card?.name || 'Card'} · ${offer.status} · ${offer.expires}`;
            row.append(title, detail);
            container.appendChild(row);
        }
        if (visible.length > 200) {
            const note = document.createElement('p');
            note.textContent = `Showing 200 of ${visible.length}; search to narrow the display. All available offers remain in the queue.`;
            container.appendChild(note);
        }
    }
    function renderPanel() {
        if (!state.panel) return;
        const panel = state.panel;
        const blocked = state.busy || Boolean(state.storageError);
        panel.getElementById('detect').disabled = blocked;
        panel.getElementById('scan').disabled = blocked || !state.selected.size;
        panel.getElementById('add').disabled = blocked || !state.selected.size || state.needsScan;
        panel.getElementById('stop').disabled = !state.busy || state.stopRequested;
        panel.getElementById('status').textContent = state.status;
        panel.getElementById('storage-error').textContent = state.storageError;
        panel.getElementById('counts').textContent = `${state.offers.length} offers · ${state.offers.filter(offer => offer.status === 'AVAILABLE').length} available · ${state.confirmed}/${state.total} added this run`;
        const cards = panel.getElementById('cards');
        cards.replaceChildren();
        for (const card of state.accounts) {
            const label = document.createElement('label');
            label.className = 'card';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.checked = state.selected.has(card.accountId);
            checkbox.disabled = state.busy;
            checkbox.setAttribute('aria-label', `Select ${card.name}`);
            checkbox.addEventListener('change', () => setCardSelected(card.accountId, checkbox.checked));
            label.append(checkbox, document.createTextNode(card.name));
            cards.appendChild(label);
        }
        renderOffers();
    }

    // Source: initialize.js
    // --- Init ---
    restorePacing();
    mountPanel();
})();
